//! Frozen vectors generated by the independent Go oracle.
use humanymous_core::challenge::proof_of_work::{issue, parse_solution, solve, verify};
use serde::Deserialize;

#[derive(Deserialize)]
struct Corpus {
    work: Vec<Work>,
    parse: Vec<Parse>,
}

#[derive(Deserialize)]
struct Work {
    key: String,
    session: String,
    bucket: u64,
    difficulty: i32,
    seed: String,
    encoded: String,
    nonce: String,
    solved: bool,
    verified: bool,
}

#[derive(Deserialize)]
struct Parse {
    input: String,
    bucket: u64,
    nonce: String,
    ok: bool,
}

#[test]
fn matches_go_oracle() {
    let corpus: Corpus = serde_json::from_str(include_str!("fixtures/proof_of_work.json")).unwrap();
    assert_eq!(
        corpus.work.len(),
        108,
        "oracle coverage must not silently shrink"
    );
    for case in corpus.work {
        let challenge = issue(
            case.key.as_bytes(),
            &case.session,
            case.difficulty,
            case.bucket,
        );
        assert_eq!(challenge.seed, case.seed);
        assert_eq!(challenge.encode(), case.encoded);
        assert_eq!(
            solve(&case.seed, case.difficulty, 4096),
            case.solved.then_some(case.nonce.clone())
        );
        assert_eq!(
            verify(
                case.key.as_bytes(),
                &case.session,
                case.difficulty,
                case.bucket,
                case.bucket,
                &case.nonce
            ),
            case.verified
        );
    }
    for case in corpus.parse {
        assert_eq!(
            parse_solution(&case.input),
            case.ok.then_some((case.bucket, case.nonce.as_str())),
            "{}",
            case.input
        );
    }
}
